import sys

def trap_best(height):
    n = len(height)
    if n == 0: return 0
    L, R = 0, n - 1
    L_max = R_max = 0
    water = 0
    while L < R:
        if height[L] < height[R]:
            if height[L] >= L_max:
                L_max = height[L]
            else:
                water += L_max - height[L]
            L += 1
        else:
            if height[R] >= R_max:
                R_max = height[R]
            else:
                water += R_max - height[R]
            R -= 1
    return water

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    n = int(data[0])
    h = list(map(int, data[1:1 + n]))
    print(trap_best(h))
